with open("word.txt", "r", encoding="utf-8") as f:
    text = f.read().lower()            # 统一成小写，避免 Python/python 分开统计

counts = {}
for w in text.split():
    counts[w] = counts.get(w, 0) + 1   # 字典计数的标准写法

top = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[:3]
for w, c in top:
    print(w, c)
